def min_tiles_to_win(hand):
    # Count the occurrences of each tile
    tile_count = Counter(hand)

    # Function to check if there is at least one mentsu (koutsu or shuntsu)
    def has_mentsu(count):
        # Check for koutsu
        for tile, count in count.items():
            if count >= 3:
                return True
        # Check for shuntsu
        suits = {'m': 'ps', 'p': 'ms', 's': 'mp'}
        for suit, other_suits in suits.items():
            for i in range(1, 8):
                if all(count[f"{i}{other_suit}"] > 0 for other_suit in other_suits):
                    return True
        return False

    # If there is already at least one mentsu, no additional tiles are needed
    if has_mentsu(tile_count):
        return 0

    # Otherwise, we need to find out how many tiles are missing to form at least one mentsu
    min_draws = float('inf')

    # Try to form a koutsu with each tile
    for tile, count in tile_count.items():
        if count < 3:
            missing = 3 - count
            remaining_tiles = {t: c for t, c in tile_count.items() if t != tile}
            if has_mentsu(remaining_tiles):
                min_draws = min(min_draws, missing)

    # Try to form a shuntsu with each starting tile
    for i in range(1, 8):
        shuntsu_tiles = {f"{i}s", f"{i+1}s", f"{i+2}s"}
        remaining_tiles = {t: c for t, c in tile_count.items() if t not in shuntsu_tiles}
        if has_mentsu(remaining_tiles):
            min_draws = min(min_draws, sum(shuntsu_tiles.count(t) for t in tile_count))

    return min_draws

